import React, { useState, useEffect } from 'react';

function App() {
  const [theme, setTheme] = useState(localStorage.getItem('theme') || 'light');
  const [name, setName] = useState('');
  const [teacher, setTeacher] = useState('');
  const [comment, setComment] = useState('');
  const [rating, setRating] = useState(0);
  const [allRatings, setAllRatings] = useState([]);

  useEffect(() => {
    document.body.className = theme === 'dark' ? 'dark-mode' : '';
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    const data = localStorage.getItem('allRatings');
    if (data) {
      setAllRatings(JSON.parse(data));
    }
  }, []);

  const submit = () => {
    if (!name || !teacher || rating === 0) {
      alert("Заповніть усі поля та виберіть оцінку");
      return;
    }

    const newEntry = { name, teacher, rating, comment, date: new Date().toLocaleString() };
    const updated = [...allRatings, newEntry];
    setAllRatings(updated);
    localStorage.setItem('allRatings', JSON.stringify(updated));
    setComment('');
    setTeacher('');
    setRating(0);
  };

  const getAverageRatings = () => {
    const stats = {};
    allRatings.forEach(r => {
      if (!stats[r.teacher]) stats[r.teacher] = [];
      stats[r.teacher].push(r.rating);
    });

    return Object.entries(stats).map(([teacher, ratings]) => ({
      teacher,
      avg: (ratings.reduce((a, b) => a + b, 0) / ratings.length).toFixed(2),
    }));
  };

  return (
    <div className="container">
      <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}>
        Змінити тему
      </button>
      <h1>Система оцінки уроків</h1>

      <input
        placeholder="Ваше ім’я"
        value={name}
        onChange={e => setName(e.target.value)}
      />
      <input
        placeholder="Ім’я викладача"
        value={teacher}
        onChange={e => setTeacher(e.target.value)}
      />

      <label>Оцініть урок:</label>
      <div>
        {[1,2,3,4,5].map(n => (
          <span
            key={n}
            className={`star ${n <= rating ? 'filled' : ''}`}
            onClick={() => setRating(n)}
          >★</span>
        ))}
      </div>

      <textarea
        placeholder="Коментар"
        value={comment}
        onChange={e => setComment(e.target.value)}
      />

      <button onClick={submit}>Надіслати оцінку</button>

      <h2>Середній рейтинг викладачів</h2>
      <table>
        <thead>
          <tr><th>Викладач</th><th>Середній бал</th></tr>
        </thead>
        <tbody>
          {getAverageRatings().map(r => (
            <tr key={r.teacher}>
              <td>{r.teacher}</td>
              <td>{r.avg}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h2>Історія оцінок</h2>
      <table>
        <thead>
          <tr><th>Ім’я</th><th>Викладач</th><th>Оцінка</th><th>Коментар</th><th>Дата</th></tr>
        </thead>
        <tbody>
          {allRatings.map((r, i) => (
            <tr key={i}>
              <td>{r.name}</td>
              <td>{r.teacher}</td>
              <td>{r.rating}</td>
              <td>{r.comment}</td>
              <td>{r.date}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
